60: static esp_err_t s_csi_claim_controller(csi_controller_t *controller)
61: {
62:     assert(controller);
63: 
64:     _lock_acquire(&s_platform.mutex);
65:     bool found = false;
66:     for (int i = 0; i < MIPI_CSI_LL_HOST_CTLR_NUMS; i ++) {
67:         found = !s_platform.controllers[i];
68:         if (found) {
69:             s_platform.controllers[i] = controller;
70:             controller->csi_id = i;
71:             PERIPH_RCC_ATOMIC() {
72:                 mipi_csi_ll_enable_host_bus_clock(i, 0);
73:                 mipi_csi_ll_enable_host_bus_clock(i, 1);
74:                 mipi_csi_ll_reset_host_clock(i);
75:             }
76:             break;
77:         }
78:     }
79:     _lock_release(&s_platform.mutex);
80: 
81:     if (!found) {
82:         return ESP_ERR_NOT_FOUND;
83:     }
84:     return ESP_OK;
85: }
