268: esp_err_t s_del_csi_ctlr(csi_controller_t *ctlr)
269: {
270:     ESP_RETURN_ON_FALSE(ctlr, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
271:     ESP_RETURN_ON_FALSE(ctlr->csi_fsm == CSI_FSM_INIT, ESP_ERR_INVALID_STATE, TAG, "processor isn't in init state");
272: 
273: #if CONFIG_PM_ENABLE
274:     if (ctlr->pm_lock) {
275:         ESP_RETURN_ON_ERROR(esp_pm_lock_delete(ctlr->pm_lock), TAG, "delete pm_lock failed");
276:     }
277: #endif // CONFIG_PM_ENABLE
278: 
279:     if (ctlr->dma_chan) {
280:         ESP_RETURN_ON_ERROR(dw_gdma_del_channel(ctlr->dma_chan), TAG, "failed to delete dwgdma channel");
281:     }
282:     //declaim first, then do free
283:     ESP_RETURN_ON_ERROR(s_csi_declaim_controller(ctlr), TAG, "declaim processor fail");
284: #if SOC_ISP_SHARE_CSI_BRG
285:     if (ctlr->csi_brg_in_use) {
286:         ESP_RETURN_ON_ERROR(mipi_csi_brg_declaim(ctlr->csi_brg_id), TAG, "declaim csi bridge fail");
287:         ctlr->csi_brg_in_use = false;
288:     }
289: #endif
290:     PERIPH_RCC_ATOMIC() {
291:         mipi_csi_ll_enable_phy_config_clock(ctlr->csi_id, 0);
292:     }
293:     if (!ctlr->bk_buffer_dis) {
294:         free(ctlr->backup_buffer);
295:     }
296:     vQueueDeleteWithCaps(ctlr->trans_que);
297:     free(ctlr);
298: 
299:     return ESP_OK;
300: }
