311:     csi_controller_t *csi_ctlr = __containerof(handle, csi_controller_t, base);
312:     ESP_RETURN_ON_FALSE((csi_ctlr->csi_fsm >= CSI_FSM_INIT) && (csi_ctlr->backup_buffer), ESP_ERR_INVALID_STATE, TAG, "driver don't initialized or back_buffer not available");
313:     ESP_RETURN_ON_FALSE(fb_num && fb_num <= 1, ESP_ERR_INVALID_ARG, TAG, "invalid frame buffer number");
314: 
315:     csi_ctlr->bk_buffer_exposed = true;
316:     const void **fb_itor = fb0;
317:     va_list args;
318:     va_start(args, fb0);
319:     for (uint32_t i = 0; i < fb_num; i++) {
320:         if (fb_itor) {
321:             *fb_itor = csi_ctlr->backup_buffer;
322:             fb_itor = va_arg(args, const void **);
323:         }
324:     }
325:     va_end(args);
326: 
327:     return ESP_OK;
328: }
