339: IRAM_ATTR static bool csi_dma_trans_done_callback(dw_gdma_channel_handle_t chan, const dw_gdma_trans_done_event_data_t *event_data, void *user_data)
340: {
341:     bool need_yield = false;
342:     BaseType_t high_task_woken = pdFALSE;
343:     csi_controller_t *ctlr = (csi_controller_t *)user_data;
344:     bool has_new_trans = false;
345: 
346:     dw_gdma_block_transfer_config_t csi_dma_transfer_config = {};
347:     csi_dma_transfer_config = (dw_gdma_block_transfer_config_t) {
348:         .src = {
349:             .addr = MIPI_CSI_BRG_MEM_BASE,
350:             .burst_mode = DW_GDMA_BURST_MODE_FIXED,
351:             .burst_items = DW_GDMA_BURST_ITEMS_512,
352:             .burst_len = 16,
353:             .width = DW_GDMA_TRANS_WIDTH_64,
354:         },
355:         .dst = {
356:             .addr = 0,
357:             .burst_mode = DW_GDMA_BURST_MODE_INCREMENT,
358:             .burst_items = DW_GDMA_BURST_ITEMS_512,
359:             .burst_len = 16,
360:             .width = DW_GDMA_TRANS_WIDTH_64,
361:         },
362:         .size = ctlr->csi_transfer_size,
363:     };
364:     esp_cam_ctlr_trans_t new_trans = {};
365: 
366:     if (ctlr->cbs.on_get_new_trans) {
367:         need_yield = ctlr->cbs.on_get_new_trans(&(ctlr->base), &new_trans, ctlr->cbs_user_data);
368:         if (new_trans.buffer && new_trans.buflen >= ctlr->fb_size_in_bytes) {
369:             csi_dma_transfer_config.dst.addr = (uint32_t)(new_trans.buffer);
370:             has_new_trans = true;
371:         }
372:     } else if (xQueueReceiveFromISR(ctlr->trans_que, &new_trans, &high_task_woken) == pdTRUE) {
373:         if (new_trans.buffer && new_trans.buflen >= ctlr->fb_size_in_bytes) {
374:             csi_dma_transfer_config.dst.addr = (uint32_t)(new_trans.buffer);
375:             has_new_trans = true;
376:         }
377:     }
378: 
379:     if (!has_new_trans) {
380:         if (!ctlr->bk_buffer_dis) {
381:             new_trans.buffer = ctlr->backup_buffer;
382:             new_trans.buflen = ctlr->fb_size_in_bytes;
383:             ESP_EARLY_LOGD(TAG, "no new buffer or no long enough new buffer, use driver internal buffer");
384:             csi_dma_transfer_config.dst.addr = (uint32_t)ctlr->backup_buffer;
385:         } else {
386:             assert(false && "no new buffer, and no driver internal buffer");
387:         }
388:     }
389: 
390:     esp_err_t ret = esp_cache_msync((void *)(new_trans.buffer), new_trans.buflen, ESP_CACHE_MSYNC_FLAG_DIR_M2C);
391:     assert(ret == ESP_OK);
392:     (void)ret;
393: 
394:     ESP_EARLY_LOGD(TAG, "new_trans.buffer: %p, new_trans.buflen: %d", new_trans.buffer, new_trans.buflen);
395:     dw_gdma_channel_config_transfer(chan, &csi_dma_transfer_config);
396:     dw_gdma_channel_enable_ctrl(chan, true);
397: 
398:     if ((ctlr->trans.buffer != ctlr->backup_buffer) || ctlr->bk_buffer_exposed) {
399:         esp_err_t ret = esp_cache_msync((void *)(ctlr->trans.buffer), ctlr->trans.received_size, ESP_CACHE_MSYNC_FLAG_DIR_M2C);
400:         assert(ret == ESP_OK);
401:         (void)ret;
402:         assert(ctlr->cbs.on_trans_finished);
